// GetEventFromName looks up an event by name (W3C SCXML 3.12).
func (p *StaticHostClockPolicy) GetEventFromName(name string) (StaticHostClockEvent, bool) {
	switch name {
	case "done.invoke":
		return StaticHostClockEventDoneInvoke, true
	case "done.invoke.now":
		return StaticHostClockEventDoneInvokeNow, true
	case "done.invoke.zone":
		return StaticHostClockEventDoneInvokeZone, true
	case "error.execution":
		return StaticHostClockEventErrorExecution, true
	case "error.invoke.now":
		return StaticHostClockEventErrorInvokeNow, true
	case "error.invoke.zone":
		return StaticHostClockEventErrorInvokeZone, true
	case "host.clock.now.request":
		return StaticHostClockEventHostClockNowRequest, true
	case "host.clock.zone.request":
		return StaticHostClockEventHostClockZoneRequest, true
	}
	return StaticHostClockEventNull, false
}

